style.css:
@-moz-document domain("youtube.com") {
:root {
    --olive-bg: #263126;
    --olive-bg2: #313B31;
    --olive-bg3: #3A453A;
    --olive-border: #4A554A;
    --olive-text: #A6B8A6;
    --olive-text2: #7E907E;
    --olive-hover: #C2D1C2;
}

/* Main background */
html,
body,
ytd-app,
#content,
#page-manager {
    background: var(--olive-bg) !important;
    color: var(--olive-text) !important;
}

/* Header */
#masthead,
tp-yt-app-header,
ytd-masthead {
    background: var(--olive-bg2) !important;
    border-bottom: 1px solid var(--olive-border) !important;
}

/* Sidebar */
#guide-content,
ytd-guide-renderer,
ytd-mini-guide-renderer,
#sections {
    background: var(--olive-bg2) !important;
}

/* Sidebar buttons */
ytd-guide-entry-renderer,
ytd-mini-guide-entry-renderer,
tp-yt-paper-item {
    border-radius: 8px !important;
}

ytd-guide-entry-renderer:hover,
ytd-mini-guide-entry-renderer:hover,
tp-yt-paper-item:hover {
    background: var(--olive-bg3) !important;
}

/* Video cards */
ytd-rich-item-renderer,
ytd-grid-video-renderer,
ytd-video-renderer,
ytd-compact-video-renderer {
    background: var(--olive-bg2) !important;
    border: 1px solid var(--olive-border) !important;
    border-radius: 12px !important;
    padding: 8px !important;
}

/* Search bar */
#search-form,
#container.ytd-searchbox,
ytd-searchbox {
    background: var(--olive-bg) !important;
    border: 1px solid var(--olive-border) !important;
}

input,
textarea {
    color: var(--olive-text) !important;
}

/* Text */
yt-formatted-string,
#video-title,
#title,
#channel-name,
#owner-name,
#description {
    color: var(--olive-text) !important;
}

/* Secondary text */
#metadata-line,
#metadata,
#subscriber-count,
#published-time-text {
    color: var(--olive-text2) !important;
}

/* Buttons */
button,
yt-button-renderer,
tp-yt-paper-button {
    background: var(--olive-bg2) !important;
    color: var(--olive-text) !important;
    border: 1px solid var(--olive-border) !important;
}

button:hover,
yt-button-renderer:hover,
tp-yt-paper-button:hover {
    background: var(--olive-bg3) !important;
    color: var(--olive-hover) !important;
}

/* Comments */
ytd-comments,
ytd-comment-thread-renderer,
ytd-comment-renderer {
    background: var(--olive-bg2) !important;
    color: var(--olive-text) !important;
}

/* Dropdown menus */
tp-yt-paper-listbox,
ytd-menu-popup-renderer,
tp-yt-iron-dropdown {
    background: var(--olive-bg2) !important;
    border: 1px solid var(--olive-border) !important;
}

/* Scrollbars */
::-webkit-scrollbar {
    width: 12px !important;
}

::-webkit-scrollbar-track {
    background: var(--olive-bg) !important;
}

::-webkit-scrollbar-thumb {
    background: var(--olive-border) !important;
}

::-webkit-scrollbar-thumb:hover {
    background: var(--olive-text2) !important;
}

/* Hover text */
a:hover,
yt-formatted-string:hover,
#video-title:hover {
    color: var(--olive-hover) !important;
}
}
